mapper.select:
select u.id, u.name, u.username, u.image, u.phone, u.status, u.update_time, d.name deptName, r.name roleName from user u left join dept d on u.dept_id = d.id left join role r on u.role_id = r.id
and u.name like concat('%',#{dto.name},'%')
and u.status = #{dto.status}
and u.phone like concat('%',#{dto.phone},'%')
and u.dept_id = #{dto.deptId}
order by update_time desc
